def transform(grid):
    h,w=len(grid),len(grid[0]);out=[row[:] for row in grid]
    top=next(r for r,row in enumerate(grid) if sum(v!=0 for v in row)>=3)
    cols=[c for c,v in enumerate(grid[top]) if v]; vals=[grid[top][c] for c in cols]
    for c,color in zip(cols,vals):
        marker=next(((r,k) for r,row in enumerate(grid) for k,v in enumerate(row) if v==color and (r!=top or k not in cols)),None)
        endrow=marker[0] if marker and marker[1]!=c else h-1
        if marker and marker[1]!=c:
            for r in range(min(top,endrow),max(top,endrow)+1): out[r][c]=color
        else:
            for r in range(h): out[r][c]=color
        if marker and marker[1]!=c:
            r,k=marker
            for x in range(min(c,k),max(c,k)+1): out[r][x]=color
    return out
